APP = ROOT / "tools/climate_analyzer/app.py"
GEOSPHERE = ROOT / "tools/climate_analyzer/epw_climate_analyzer/geosphere.py"
DOC_065 = ROOT / "tools/climate_analyzer/CLIMATE_CORE_0_6_5.md"
DOC_067 = ROOT / "tools/climate_analyzer/CLIMATE_CORE_0_6_7.md"
