def replace_once(text: str, old: str, new: str, *, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected exactly one match, found {count}")
    return text.replace(old, new, 1)


# ---------------------------------------------------------------------------
# GeoSphere transport: add observational progress events without changing the
# numerical/provider semantics of retries, splitting, parsing or fail-closed
# behavior.
# ---------------------------------------------------------------------------
geosphere = GEOSPHERE.read_text(encoding="utf-8")
geosphere = replace_once(
    geosphere,
    "from typing import Any, Iterable, Mapping",
    "from typing import Any, Callable, Iterable, Mapping",
    label="typing import",
)

split_block = '''def _split_data_query(query: Mapping[str, str]) -> tuple[dict[str, str], dict[str, str]] | None:\n    \"\"\"Bisect one inclusive query on the native 10-minute grid without overlap.\"\"\"\n    parameters = tuple(item for item in str(query.get(\"parameters\", \"\")).split(\",\") if item)\n    station_id = str(query.get(\"station_ids\", \"\")).strip()\n    if not station_id or not parameters:\n        raise ValueError(\"GeoSphere query is missing station or parameter identity.\")\n    start = pd.Timestamp(str(query.get(\"start\", \"\")), tz=\"UTC\")\n    end = pd.Timestamp(str(query.get(\"end\", \"\")), tz=\"UTC\")\n    interval = pd.Timedelta(minutes=GEOSPHERE_NATIVE_INTERVAL_MINUTES)\n    steps = int(math.floor((end - start) / interval)) + 1\n    if steps <= 1:\n        return None\n    left_steps = max(1, steps // 2)\n    left_end = start + interval * (left_steps - 1)\n    right_start = left_end + interval\n    if right_start > end:\n        return None\n    return (\n        build_data_query(station_id, start, left_end, parameters),\n        build_data_query(station_id, right_start, end, parameters),\n    )\n\n\n'''
progress_block = split_block + '''GeoSphereProgressCallback = Callable[[Mapping[str, object]], None]\n\n\ndef _emit_progress(\n    progress_callback: GeoSphereProgressCallback | None,\n    *,\n    event: str,\n    completed_batches: int,\n    total_batches: int,\n    batch_number: int,\n    query: Mapping[str, str],\n    attempt: int | None = None,\n    split_depth: int = 0,\n) -> None:\n    \"\"\"Emit best-effort transport progress without affecting data loading.\n\n    Progress is observational only. A UI callback failure must never alter the\n    provider request, scientific data, retry policy or fail-closed behavior.\n    The denominator is the original set of planned root batches; adaptive child\n    requests remain inside the currently active root batch.\n    \"\"\"\n    if progress_callback is None:\n        return\n    payload: dict[str, object] = {\n        \"event\": str(event),\n        \"completed_batches\": int(completed_batches),\n        \"total_batches\": int(total_batches),\n        \"batch_number\": int(batch_number),\n        \"split_depth\": int(split_depth),\n        \"start\": str(query.get(\"start\", \"\")),\n        \"end\": str(query.get(\"end\", \"\")),\n    }\n    if attempt is not None:\n        payload[\"attempt\"] = int(attempt)\n    try:\n        progress_callback(payload)\n    except Exception:\n        # Rendering/status reporting is deliberately non-critical.\n        return\n\n\n'''
geosphere = replace_once(geosphere, split_block, progress_block, label="progress helper insertion")

old_fetch_signature = '''def _fetch_query_with_resilience(\n    query: Mapping[str, str],\n    *,\n    timeout_s: int,\n    split_depth: int = 0,\n) -> list[tuple[dict[str, Any], dict[str, str]]]:'''
new_fetch_signature = '''def _fetch_query_with_resilience(\n    query: Mapping[str, str],\n    *,\n    timeout_s: int,\n    split_depth: int = 0,\n    progress_callback: GeoSphereProgressCallback | None = None,\n    root_batch_number: int = 1,\n    root_batch_count: int = 1,\n    completed_root_batches: int = 0,\n) -> list[tuple[dict[str, Any], dict[str, str]]]:'''
geosphere = replace_once(geosphere, old_fetch_signature, new_fetch_signature, label="resilience signature")

old_retry = '''            if attempt < MAX_TRANSIENT_ATTEMPTS:\n                time.sleep(RETRY_BACKOFF_BASE_SECONDS * (2 ** (attempt - 1)))\n                continue\n            break\n'''
new_retry = '''            if attempt < MAX_TRANSIENT_ATTEMPTS:\n                _emit_progress(\n                    progress_callback,\n                    event=\"retry\",\n                    completed_batches=completed_root_batches,\n                    total_batches=root_batch_count,\n                    batch_number=root_batch_number,\n                    query=normalized_query,\n                    attempt=attempt + 1,\n                    split_depth=split_depth,\n                )\n                time.sleep(RETRY_BACKOFF_BASE_SECONDS * (2 ** (attempt - 1)))\n                continue\n            break\n'''
geosphere = replace_once(geosphere, old_retry, new_retry, label="retry progress")

old_children = '''    children = _split_data_query(normalized_query)\n    if children is None:\n        raise RuntimeError(\n            f\"GeoSphere single-interval batch failed after retries: \"\n            f\"{normalized_query.get('start')} → {normalized_query.get('end')}.\"\n        ) from last_error\n\n    completed: list[tuple[dict[str, Any], dict[str, str]]] = []\n    for child in children:\n        completed.extend(\n            _fetch_query_with_resilience(child, timeout_s=timeout_s, split_depth=split_depth + 1)\n        )\n    return completed\n'''
new_children = '''    children = _split_data_query(normalized_query)\n    if children is None:\n        raise RuntimeError(\n            f\"GeoSphere single-interval batch failed after retries: \"\n            f\"{normalized_query.get('start')} → {normalized_query.get('end')}.\"\n        ) from last_error\n\n    _emit_progress(\n        progress_callback,\n        event=\"split\",\n        completed_batches=completed_root_batches,\n        total_batches=root_batch_count,\n        batch_number=root_batch_number,\n        query=normalized_query,\n        split_depth=split_depth + 1,\n    )\n    completed: list[tuple[dict[str, Any], dict[str, str]]] = []\n    for child in children:\n        completed.extend(\n            _fetch_query_with_resilience(\n                child,\n                timeout_s=timeout_s,\n                split_depth=split_depth + 1,\n                progress_callback=progress_callback,\n                root_batch_number=root_batch_number,\n                root_batch_count=root_batch_count,\n                completed_root_batches=completed_root_batches,\n            )\n        )\n    return completed\n'''
geosphere = replace_once(geosphere, old_children, new_children, label="split progress")

old_provider = '''def fetch_station_provider_frame(\n    *,\n    station_id: str,\n    start: pd.Timestamp,\n    end: pd.Timestamp,\n    provider_parameters: Iterable[str],\n    timeout_s: int = DEFAULT_TIMEOUT_SECONDS,\n) -> tuple[pd.DataFrame, tuple[str, ...]]:\n'''
new_provider = '''def fetch_station_provider_frame(\n    *,\n    station_id: str,\n    start: pd.Timestamp,\n    end: pd.Timestamp,\n    provider_parameters: Iterable[str],\n    timeout_s: int = DEFAULT_TIMEOUT_SECONDS,\n    progress_callback: GeoSphereProgressCallback | None = None,\n) -> tuple[pd.DataFrame, tuple[str, ...]]:\n'''
geosphere = replace_once(geosphere, old_provider, new_provider, label="provider frame signature")

old_loop = '''    frames: list[pd.DataFrame] = []\n    references: list[str] = []\n    for query in queries:\n        completed = _fetch_query_with_resilience(query, timeout_s=timeout_s)\n        for payload, successful_query in completed:\n            frames.append(parse_station_data_response(payload, station_id, parameters))\n            references.append(_query_reference(successful_query))\n\n    if not frames:\n'''
new_loop = '''    frames: list[pd.DataFrame] = []\n    references: list[str] = []\n    total_batches = len(queries)\n    for batch_number, query in enumerate(queries, start=1):\n        _emit_progress(\n            progress_callback,\n            event=\"batch_start\",\n            completed_batches=batch_number - 1,\n            total_batches=total_batches,\n            batch_number=batch_number,\n            query=query,\n        )\n        completed = _fetch_query_with_resilience(\n            query,\n            timeout_s=timeout_s,\n            progress_callback=progress_callback,\n            root_batch_number=batch_number,\n            root_batch_count=total_batches,\n            completed_root_batches=batch_number - 1,\n        )\n        for payload, successful_query in completed:\n            frames.append(parse_station_data_response(payload, station_id, parameters))\n            references.append(_query_reference(successful_query))\n        _emit_progress(\n            progress_callback,\n            event=\"batch_complete\",\n            completed_batches=batch_number,\n            total_batches=total_batches,\n            batch_number=batch_number,\n            query=query,\n        )\n\n    if queries:\n        _emit_progress(\n            progress_callback,\n            event=\"load_complete\",\n            completed_batches=total_batches,\n            total_batches=total_batches,\n            batch_number=total_batches,\n            query=queries[-1],\n        )\n\n    if not frames:\n'''
geosphere = replace_once(geosphere, old_loop, new_loop, label="provider frame loop")

old_dataset_signature = '''def fetch_station_dataset(\n    *,\n    station: GeoSphereStation,\n    start: pd.Timestamp,\n    end: pd.Timestamp,\n    metadata: Mapping[str, Any] | None = None,\n    canonical_variables: Iterable[str] | None = None,\n    timeout_s: int = DEFAULT_TIMEOUT_SECONDS,\n) -> CanonicalClimateDataset:\n'''
new_dataset_signature = '''def fetch_station_dataset(\n    *,\n    station: GeoSphereStation,\n    start: pd.Timestamp,\n    end: pd.Timestamp,\n    metadata: Mapping[str, Any] | None = None,\n    canonical_variables: Iterable[str] | None = None,\n    timeout_s: int = DEFAULT_TIMEOUT_SECONDS,\n    progress_callback: GeoSphereProgressCallback | None = None,\n) -> CanonicalClimateDataset:\n'''
geosphere = replace_once(geosphere, old_dataset_signature, new_dataset_signature, label="dataset signature")

old_dataset_call = '''    provider_frame, request_references = fetch_station_provider_frame(\n        station_id=station.station_id,\n        start=start,\n        end=end,\n        provider_parameters=selected.keys(),\n        timeout_s=timeout_s,\n    )\n'''
new_dataset_call = '''    provider_frame, request_references = fetch_station_provider_frame(\n        station_id=station.station_id,\n        start=start,\n        end=end,\n        provider_parameters=selected.keys(),\n        timeout_s=timeout_s,\n        progress_callback=progress_callback,\n    )\n'''
geosphere = replace_once(geosphere, old_dataset_call, new_dataset_call, label="dataset progress passthrough")
GEOSPHERE.write_text(geosphere, encoding="utf-8")


# ---------------------------------------------------------------------------
# Streamlit UX: replace the indeterminate spinner with root-batch progress.
# Retries and adaptive split children remain within the current root batch, so
# the denominator does not jump during provider recovery.
# ---------------------------------------------------------------------------
app = APP.read_text(encoding="utf-8")
old_app = '''    if st.button(\"Load measured GeoSphere interval\", type=\"primary\", key=\"load_geosphere_interval\"):\n        try:\n            with st.spinner(f\"Loading {len(batches)} bounded GeoSphere request batch(es)...\"):\n                dataset = fetch_geosphere_station_dataset(\n                    station=station,\n                    start=start_ts,\n                    end=end_ts,\n                    metadata=metadata,\n                    canonical_variables=canonical_variables,\n                )\n            set_active_canonical_climate(dataset)\n            st.rerun()\n        except Exception as exc:\n            st.error(f\"GeoSphere station-data load failed: {exc}\")\n'''
new_app = '''    if st.button(\"Load measured GeoSphere interval\", type=\"primary\", key=\"load_geosphere_interval\"):\n        progress_state = {\"completed\": 0, \"total\": max(1, len(batches))}\n        progress_bar = st.progress(\n            0.0,\n            text=f\"GeoSphere load — 0/{len(batches)} planned batch(es) complete\",\n        )\n\n        def update_geosphere_progress(event) -> None:\n            total = max(1, int(event.get(\"total_batches\", len(batches))))\n            completed = min(total, max(0, int(event.get(\"completed_batches\", 0))))\n            batch_number = min(total, max(1, int(event.get(\"batch_number\", completed + 1))))\n            progress_state[\"completed\"] = completed\n            progress_state[\"total\"] = total\n            event_name = str(event.get(\"event\", \"\"))\n            if event_name == \"batch_start\":\n                label = f\"Loading GeoSphere batch {batch_number}/{total}...\"\n            elif event_name == \"retry\":\n                attempt = int(event.get(\"attempt\", 2))\n                label = f\"GeoSphere batch {batch_number}/{total}: transient provider error — retry {attempt}...\"\n            elif event_name == \"split\":\n                split_depth = int(event.get(\"split_depth\", 1))\n                label = (\n                    f\"GeoSphere batch {batch_number}/{total}: provider response still slow — \"\n                    f\"splitting this batch (level {split_depth})...\"\n                )\n            elif event_name == \"batch_complete\":\n                label = f\"GeoSphere load — {completed}/{total} planned batch(es) complete\"\n            elif event_name == \"load_complete\":\n                label = f\"GeoSphere load complete — {completed}/{total} planned batch(es)\"\n            else:\n                label = f\"GeoSphere load — {completed}/{total} planned batch(es) complete\"\n            progress_bar.progress(completed / total, text=label)\n\n        try:\n            dataset = fetch_geosphere_station_dataset(\n                station=station,\n                start=start_ts,\n                end=end_ts,\n                metadata=metadata,\n                canonical_variables=canonical_variables,\n                progress_callback=update_geosphere_progress,\n            )\n            progress_bar.progress(\n                1.0,\n                text=f\"GeoSphere load complete — {len(batches)}/{len(batches)} planned batch(es)\",\n            )\n            set_active_canonical_climate(dataset)\n            st.rerun()\n        except Exception as exc:\n            total = max(1, int(progress_state[\"total\"]))\n            completed = min(total, max(0, int(progress_state[\"completed\"])))\n            progress_bar.progress(\n                completed / total,\n                text=f\"GeoSphere load stopped — {completed}/{total} planned batch(es) complete\",\n            )\n            st.error(f\"GeoSphere station-data load failed: {exc}\")\n'''
app = replace_once(app, old_app, new_app, label="Streamlit GeoSphere load block")
APP.write_text(app, encoding="utf-8")


